/**
 * Console API contract registered with the zod contract registry and rendered as
 * schemas/openapi/console.openapi.json (FO-04-01; generated by generate-schemas.ts, drift-checked by
 * `pnpm --filter @vsp/platform schemas:check`, which CI runs).
 *
 * The single zod source for the console API stays platform/src/console-api/schemas.ts
 * (ENDPOINT_SCHEMAS, PATH_PARAM_SCHEMAS: strict request and response schemas that the backend
 * parses every response with), with the routes and roles in platform/src/console-api/contract.ts.
 * This module only reads them; it is generator-only and is not re-exported from the protocol barrel,
 * so runtime protocol consumers never depend on the console module.
 */
import { z } from "zod";
import {
  AUTHORIZATION_HEADER,
  CONSOLE_API_BASE,
  CONSOLE_API_VERSION,
  CONSOLE_ENDPOINTS,
  ENDPOINT_ROLES,
  IDEMPOTENCY_HEADER,
  IDEMPOTENCY_KEY_PATTERN,
  PUBLIC_ENDPOINTS,
  type AuthenticatedEndpointKey,
  type EndpointKey,
  type PathParamName,
} from "../console-api/contract.js";
import { ConsoleErrorBodyS, ENDPOINT_SCHEMAS, PATH_PARAM_SCHEMAS } from "../console-api/schemas.js";

export const CONSOLE_OPENAPI_PATH = "schemas/openapi/console.openapi.json";

type Json = Record<string, unknown>;

function strip(node: unknown): unknown {
  if (Array.isArray(node)) return node.map(strip);
  if (typeof node !== "object" || node === null) return node;
  const out: Json = {};
  for (const [k, v] of Object.entries(node as Json)) if (k !== "$schema") out[k] = strip(v);
  return out;
}

/** JSON Schema 2020-12 of the request ("input") view; strict objects keep additionalProperties:false. */
const inputSchema = (s: z.ZodType): Json => strip(z.toJSONSchema(s, { target: "draft-2020-12", io: "input" })) as Json;
/** JSON Schema of what the server sends (responses are parsed with the schema before sending). */
const outputSchema = (s: z.ZodType): Json => strip(z.toJSONSchema(s, { target: "draft-2020-12", io: "output" })) as Json;

const isPublic = (k: EndpointKey): boolean => (PUBLIC_ENDPOINTS as readonly string[]).includes(k);

/** Mutations requiring a client Idempotency-Key: authenticated POSTs except logout (console-api/plugin.ts). */
export const idempotentEndpoint = (k: EndpointKey): boolean => !isPublic(k) && CONSOLE_ENDPOINTS[k].method === "POST" && k !== "auth.logout";

const errorRef = { $ref: "#/components/schemas/ConsoleErrorBody" };
const err = (description: string): Json => ({ description, content: { "application/json": { schema: errorRef } } });

function operation(key: EndpointKey): Json {
  const spec = CONSOLE_ENDPOINTS[key];
  const schemas = ENDPOINT_SCHEMAS[key];
  const parameters: Json[] = [];
  for (const m of spec.path.matchAll(/:([A-Za-z]+)/g)) {
    const name = m[1] as PathParamName;
    const ps = PATH_PARAM_SCHEMAS[name];
    if (!ps) throw new Error(`CONSOLE_OPENAPI_UNKNOWN_PATH_PARAM:${key}:${name}`);
    parameters.push({ name, in: "path", required: true, schema: inputSchema(ps) });
  }
  if (schemas.query) {
    const qs = inputSchema(schemas.query);
    const props = (qs.properties ?? {}) as Record<string, Json>;
    const required = new Set((qs.required ?? []) as string[]);
    for (const name of Object.keys(props).sort()) parameters.push({ name, in: "query", required: required.has(name), schema: props[name] });
  }
  if (!isPublic(key)) {
    parameters.push({ name: AUTHORIZATION_HEADER, in: "header", required: true, description: "Bearer token from the console token endpoints (memory only)", schema: { type: "string", maxLength: 4096 } });
  }
  if (idempotentEndpoint(key)) {
    parameters.push({ name: IDEMPOTENCY_HEADER, in: "header", required: true, description: "Client key per confirmed mutation; a repeat returns the first result", schema: { type: "string", pattern: IDEMPOTENCY_KEY_PATTERN } });
  }

  const responses: Json = {
    "200": { description: "OK", content: { "application/json": { schema: outputSchema(schemas.response) } } },
    "400": err("VALIDATION_FAILED and other reason codes: invalid path, query or body"),
    "500": err("INTERNAL_ERROR or RESPONSE_SCHEMA_VIOLATION (fail closed)"),
    "503": err("AUDIT_UNAVAILABLE or dependency unavailable (retryable)"),
  };
  if (!isPublic(key)) {
    responses["401"] = err("UNAUTHENTICATED: missing, expired or revoked staff token");
    responses["403"] = err("STAFF_ROLE_NOT_PERMITTED or a finer per-scope rule");
  }
  if (spec.method === "POST") responses["409"] = err("STATE_CONFLICT or idempotency conflict");
  if (parameters.some((p) => p.in === "path")) responses["404"] = err("NOT_FOUND");
  if (key === "auth.localStaff" || key === "auth.localToken") responses["404"] = err("LOCAL_FIXTURE_DISABLED outside local/ci");
  const sortedResponses: Json = {};
  for (const code of Object.keys(responses).sort()) sortedResponses[code] = responses[code];

  const op: Json = {
    operationId: `console.${key}`,
    tags: [key.split(".")[0]],
    security: isPublic(key) ? [] : [{ staffBearer: [] }],
    "x-vsp-roles": isPublic(key) ? [] : [...ENDPOINT_ROLES[key as AuthenticatedEndpointKey]].sort(),
    "x-vsp-idempotent": idempotentEndpoint(key),
  };
  if (parameters.length > 0) op.parameters = parameters;
  if (spec.method === "POST") {
    op.requestBody = { required: true, content: { "application/json": { schema: schemas.body ? inputSchema(schemas.body) : { type: "object", properties: {}, additionalProperties: false } } } };
  }
  op.responses = sortedResponses;
  return op;
}

/** Deterministic OpenAPI 3.1 document for every console endpoint. */
export function buildConsoleOpenApi(): Json {
  const paths: Record<string, Json> = {};
  const keys = (Object.keys(CONSOLE_ENDPOINTS) as EndpointKey[]).sort();
  for (const key of keys) {
    const spec = CONSOLE_ENDPOINTS[key];
    if (!spec.path.startsWith(`${CONSOLE_API_BASE}/`)) throw new Error(`CONSOLE_OPENAPI_PATH_OUTSIDE_BASE:${key}`);
    const p = spec.path.replace(/:([A-Za-z]+)/g, "{$1}");
    const item = (paths[p] ??= {});
    const method = spec.method.toLowerCase();
    if (item[method]) throw new Error(`CONSOLE_OPENAPI_DUPLICATE_ROUTE:${spec.method} ${spec.path}`);
    item[method] = operation(key);
  }
  const sortedPaths: Record<string, Json> = {};
  for (const p of Object.keys(paths).sort()) sortedPaths[p] = paths[p] as Json;
  return {
    openapi: "3.1.0",
    jsonSchemaDialect: "https://json-schema.org/draft/2020-12/schema",
    info: {
      title: "Voice Support Platform operations console API",
      version: CONSOLE_API_VERSION,
      description:
        "GENERATED by platform/src/protocol/generate-schemas.ts from the zod console contract (platform/src/console-api/schemas.ts and contract.ts); do not edit. Workforce SSO with MFA; roles are server-established (x-vsp-roles) and enforced server-side. Content-free: no transcript, audio, recording, raw query or task token field exists.",
    },
    servers: [{ url: "/" }],
    paths: sortedPaths,
    components: {
      schemas: { ConsoleErrorBody: outputSchema(ConsoleErrorBodyS) },
      securitySchemes: { staffBearer: { type: "http", scheme: "bearer", description: "Console staff token (workforce SSO); held in browser memory only" } },
    },
  };
}

export const renderConsoleOpenApi = (): string => JSON.stringify(buildConsoleOpenApi(), null, 2) + "\n";
